// Ultra Deluxe: attack animations, the title intro and the end credits.
// Frames live in AnimationData.cpp (generated by tools/gen_animations.py).
#ifndef ULTRA_DELUXE_ANIMATIONS_H
#define ULTRA_DELUXE_ANIMATIONS_H

class character;

struct UDFrame {
	int holdMs;		// how long to show it (0 = use the sequence's default)
	const char* art;	// raw string literal, starts and ends with a newline
};

extern const UDFrame UD_ANIM_BROOMBA_SMALL[];
extern const int UD_ANIM_BROOMBA_SMALL_COUNT;
extern const UDFrame UD_ANIM_BROOMBA_LARGE[];	// kept for later
extern const int UD_ANIM_BROOMBA_LARGE_COUNT;
extern const UDFrame UD_ANIM_JETWET_SMALL[];
extern const int UD_ANIM_JETWET_SMALL_COUNT;
extern const UDFrame UD_ANIM_JETWET_LARGE[];	// kept for later
extern const int UD_ANIM_JETWET_LARGE_COUNT;
extern const UDFrame UD_ANIM_BYSONV8_SMALL[];
extern const int UD_ANIM_BYSONV8_SMALL_COUNT;
extern const UDFrame UD_ANIM_BYSONV8_LARGE[];	// kept for later
extern const int UD_ANIM_BYSONV8_LARGE_COUNT;
extern const UDFrame UD_ANIM_TITLE[];
extern const int UD_ANIM_TITLE_COUNT;
extern const UDFrame UD_ANIM_CREDITS[];
extern const int UD_ANIM_CREDITS_COUNT;

// The player's small attack animation: ~120 ms per frame, the hit held ~500 ms.
void ud_playAttackAnimation(character& c);

// Title intro at launch. Enter skips it at any point; once it finishes,
// the last 4 frames loop until Enter is pressed.
void ud_playTitle();

// Ending + credits sequence (replaces the old end credits screen).
void ud_playCredits();

// The player's small front art, drawn to the right of the battle menu
// (or above it when the screen is too narrow). Call just before the menu.
void ud_showArtBesideMenu(character& c);

#endif
